from math import gcd

def _rand_reduced_fraction(rng, min_den=3, max_den=12):
    d = rng.randint(min_den, max_den)
    n = rng.randint(1, d-1)
    while gcd(n, d) != 1:
        n = rng.randint(1, d-1)
    return n, d

def _ordinal(n):
    if 11 <= (n % 100) <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')
    return f"{n}{suf}"

